{"cards": [{"node_code": "N_0c525f631b0bddc9", "definition": "研究气液或液液两相流中宏观流动形态分类、相间分布特征（空隙率）及流动阻力（压降）特性的分支。", "boundary": "聚焦于两相流的宏观统计特性与工程参数。涵盖流型图构建、空隙率分布模型、摩擦压降及加速压降计算。与“环状流、段塞流与分层流”的区别在于本节点侧重通用参数与规律，而非特定流型的微观结构；与“气泡、液滴与界面动力学”的区别在于本节点关注整体输运特性，而非离散相的个体行为。", "includes": ["两相流流型判别准则与流型图", "空隙率（含气率）分布规律及预测模型", "两相流摩擦压降、重位压降及总压降计算"], "excludes": ["特定流型（如环状流）的界面波动细节（归入环状流、段塞流与分层流）", "单个气泡或液滴的变形、破碎机理（归入气泡、液滴与界面动力学）"], "sibling_distinctions": [{"other_code": "N_97cf28181e6efd89", "rule": "本节点侧重宏观参数（空隙率、压降）的通用规律；兄弟节点侧重特定流型（环状、段塞、分层）的结构特征与演化。"}, {"other_code": "N_5fe96fcd02131539", "rule": "本节点关注整体流动阻力与分布；兄弟节点关注离散相（气泡/液滴）的微观动力学行为。"}], "cross_boundary_rule": "若研究重点为特定流型下的压降机制，主挂载至“环状流、段塞流与分层流”；若为通用两相流压降关联式或空隙率模型，主挂载至本节点。"}, {"node_code": "N_5fe96fcd02131539", "definition": "研究气液或液液两相流中离散相（气泡、液滴）的生成、运动、变形、破碎及聚并等微观动力学过程。", "boundary": "聚焦于离散相的个体行为及其与连续相的相互作用。涵盖气泡/液滴的受力分析、界面稳定性、表面张力效应及湍流中的相分散。与“流型、空隙率与压降”的区别在于本节点关注微观尺度机制，而非宏观统计参数；与“环状流、段塞流与分层流”的区别在于本节点不局限于特定流型，而是研究离散相的通用动力学。", "includes": ["气泡与液滴的生成、破碎与聚并机理", "离散相在连续相中的运动轨迹与受力分析", "相界面的变形、振荡及稳定性分析"], "excludes": ["宏观流型转换或整体压降特性（归入流型、空隙率与压降）", "特定流型（如段塞流）中液塞的整体运动（归入环状流、段塞流与分层流）"], "sibling_distinctions": [{"other_code": "N_0c525f631b0bddc9", "rule": "本节点侧重微观离散相动力学；兄弟节点侧重宏观流动参数与阻力。"}, {"other_code": "N_97cf28181e6efd89", "rule": "本节点研究离散相的通用行为；兄弟节点研究特定流型下的整体结构演化。"}], "cross_boundary_rule": "若研究离散相行为对宏观流型形成的影响，可关联“环状流、段塞流与分层流”；若仅研究离散相本身的动力学，主挂载至本节点。"}, {"node_code": "N_97cf28181e6efd89", "definition": "研究环状流、段塞流、分层流等典型气液或液液两相流动形态的结构特征、演化规律及转换机制。", "boundary": "聚焦于特定宏观流型的物理结构及其稳定性。涵盖各流型的界面形态、速度分布、流型转换边界及动态演化过程。与“流型、空隙率与压降”的区别在于本节点深入特定流型的内部结构，而非通用参数；与“气泡、液滴与界面动力学”的区别在于本节点关注整体流型结构，而非单个离散相行为。", "includes": ["环状流、段塞流、分层流等典型流型的结构特征", "流型转换的临界条件与动态演化过程", "特定流型下的速度场、压力场分布"], "excludes": ["通用两相流压降关联式或空隙率模型（归入流型、空隙率与压降）", "单个气泡或液滴的微观动力学（归入气泡、液滴与界面动力学）"], "sibling_distinctions": [{"other_code": "N_0c525f631b0bddc9", "rule": "本节点侧重特定流型的结构与演化；兄弟节点侧重通用宏观参数与规律。"}, {"other_code": "N_5fe96fcd02131539", "rule": "本节点关注整体流型结构；兄弟节点关注离散相的微观行为。"}], "cross_boundary_rule": "若研究特定流型下的压降或空隙率，主挂载至本节点；若为不区分流型的通用模型，主挂载至“流型、空隙率与压降”。"}]}
